python3 - <<'EOF'
import re
p='src/tasks.ts'
s=open(p).read()
s=s.replace('''export function listTasks(db: Database): Task[] {
  return db.all("SELECT * FROM tasks ORDER BY id") as unknown as Task[];
}
''','''export const DEFAULT_PAGE_SIZE = 50;
export const MAX_PAGE_SIZE = 200;

export interface TaskPage {
  tasks: Task[];
  /** Tasks matching the search, across all pages. */
  total: number;
  limit: number;
  offset: number;
}

export interface ListOptions {
  /** Case-insensitive substring of the title; empty means no filter. */
  search?: string;
  limit?: number;
  offset?: number;
}

/** Escapes LIKE wildcards so the search text is matched literally. */
function likePattern(search: string): string {
  return `%${search.replace(/[\\\\%_]/g, "\\\\$&")}%`;
}

/** Open tasks first, then completed ones; newest first inside each group. */
export function listTasks(db: Database, options: ListOptions = {}): TaskPage {
  const { search = "", limit = DEFAULT_PAGE_SIZE, offset = 0 } = options;
  const term = search.trim();
  const where = term ? "WHERE title LIKE ? ESCAPE '\\\\'" : "";
  const filter = term ? [likePattern(term)] : [];

  const [{ total }] = db.all(`SELECT COUNT(*) AS total FROM tasks ${where}`, ...filter) as {
    total: number;
  }[];
  const tasks = db.all(
    `SELECT * FROM tasks ${where} ORDER BY (completed_at IS NOT NULL), id DESC LIMIT ? OFFSET ?`,
    ...filter,
    limit,
    offset,
  ) as unknown as Task[];

  return { tasks, total, limit, offset };
}
''')
open(p,'w').write(s)

p='src/app.ts'
