s=s.replace('import { createTask, listTasks } from "./tasks.ts";','import { createTask, DEFAULT_PAGE_SIZE, listTasks, MAX_PAGE_SIZE } from "./tasks.ts";')
s=s.replace('''  app.get("/api/tasks", (c) => c.json({ tasks: listTasks(db) }));
''','''  app.get("/api/tasks", (c) => {
    const limit = parseCount(c.req.query("limit"), DEFAULT_PAGE_SIZE, 1, MAX_PAGE_SIZE);
    const offset = parseCount(c.req.query("offset"), 0, 0, Number.MAX_SAFE_INTEGER);
    if (limit === null || offset === null) {
      return c.json(
        {
          error: {
            code: "validation_failed",
            message: `limit must be an integer from 1 to ${MAX_PAGE_SIZE} and offset an integer from 0`,
          },
        },
        400,
      );
    }
    return c.json(listTasks(db, { search: c.req.query("q"), limit, offset }));
  });
''')
s=s.replace('''export function createApp''','''/** Parses an optional integer query value; null when present but not an integer in range. */
function parseCount(raw: string | undefined, fallback: number, min: number, max: number) {
  if (raw === undefined) return fallback;
  const value = Number(raw);
  return raw.trim() !== "" && Number.isInteger(value) && value >= min && value <= max
    ? value
    : null;
}

export function createApp''')
